import "server-only";
import { createClient } from "@supabase/supabase-js";
import { createSupabaseServerClient } from "@/lib/supabase/server";
import { supabasePublishableKey, supabaseUrl } from "@/lib/supabase/config";
import { unauthorized } from "./http";
import { prisma } from "./prisma";

// Who is calling. Identity comes from Supabase Auth (a verified JWT); the role
// and organization come ONLY from our tables (memberships for staff/managers,
// tenants.user_id for tenants) — never from user_metadata, which users can edit.

export type Actor =
  | {
      kind: "member";
      userId: string;
      email: string | null;
      orgId: string;
      role: "manager" | "staff";
    }
  | {
      kind: "tenant";
      userId: string;
      email: string | null;
      orgId: string;
      tenantId: string;
    };

type AuthUser = { id: string; email: string | null };

const BEARER_PATTERN = /^Bearer\s+(\S+)$/i;

// Authorization: Bearer <access token> (how the graders' tests call the API).
// getUser(token) asks the Auth server to verify the token — not a local decode.
const userFromBearer = async (token: string): Promise<AuthUser | null> => {
  const supabase = createClient(supabaseUrl(), supabasePublishableKey(), {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
  const { data, error } = await supabase.auth.getUser(token);
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

// The browser session cookie. getUser(), never getSession(): getSession trusts
// the cookie's contents without asking the Auth server.
const userFromCookie = async (): Promise<AuthUser | null> => {
  const supabase = await createSupabaseServerClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

const authUser = async (req?: Request): Promise<AuthUser | null> => {
  const header = req?.headers.get("authorization");
  if (header) {
    const match = BEARER_PATTERN.exec(header.trim());
    // A malformed Authorization header is not silently ignored in favour of
    // a cookie: the caller asked to authenticate with it, and it is invalid.
    return match?.[1] ? userFromBearer(match[1]) : null;
  }
  return userFromCookie();
};

/** Resolves the caller to an Actor, or null when there is no valid login or no role. */
export const getActor = async (req?: Request): Promise<Actor | null> => {
  const user = await authUser(req);
  if (!user) {
    return null;
  }
  const membership = await prisma.memberships.findUnique({
    where: { user_id: user.id },
    select: { org_id: true, role: true },
  });
  if (membership) {
    if (membership.role !== "manager" && membership.role !== "staff") {
      return null;
    }
    return {
      kind: "member",
      userId: user.id,
      email: user.email,
      orgId: membership.org_id,
      role: membership.role,
    };
  }
  const tenant = await prisma.tenants.findUnique({
    where: { user_id: user.id },
    select: { id: true, org_id: true },
  });
  if (tenant) {
    return {
      kind: "tenant",
      userId: user.id,
      email: user.email,
      orgId: tenant.org_id,
      tenantId: tenant.id,
    };
  }
  return null;
};

/** getActor or 401. */
export const requireActor = async (req?: Request): Promise<Actor> => {
  const actor = await getActor(req);
  if (!actor) {
    throw unauthorized();
  }
  return actor;
};
import "server-only";
import type { leases, payments } from "@/generated/prisma/client";
import type { Actor } from "./auth";
import { forbidden, notFound } from "./http";
import { prisma } from "./prisma";
import type { Tx } from "./allocation";

// Record visibility (-> 404) and role checks (-> 403), shared by every service.
// Prisma bypasses RLS, so these ARE the authorization for server code. No
// next/headers here: seed scripts and tests call services with a hand-made Actor.

type Db = Tx | typeof prisma;
export type MemberActor = Extract<Actor, { kind: "member" }>;
export type ManagerActor = MemberActor & { role: "manager" };

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const isUuid = (value: unknown): value is string =>
  typeof value === "string" && UUID_PATTERN.test(value);

// The org filter is part of the query, so a record in another organization is
// indistinguishable from one that does not exist.
const leaseScope = (actor: Actor) =>
  actor.kind === "tenant"
    ? { org_id: actor.orgId, tenant_id: actor.tenantId }
    : { org_id: actor.orgId };

/** The lease if the actor may see it, else null (bad id, other org, other tenant). */
export const findVisibleLease = async (
  actor: Actor,
  leaseId: string,
  tx: Db = prisma,
): Promise<leases | null> => {
  if (!isUuid(leaseId)) {
    return null;
  }
  return tx.leases.findFirst({ where: { id: leaseId, ...leaseScope(actor) } });
};

export const requireVisibleLease = async (
  actor: Actor,
  leaseId: string,
  tx: Db = prisma,
): Promise<leases> => {
  const lease = await findVisibleLease(actor, leaseId, tx);
  if (!lease) {
    throw notFound();
  }
  return lease;
};

/** The payment if the actor may see it (tenant: only payments on their own leases). */
export const findVisiblePayment = async (
  actor: Actor,
  paymentId: string,
  tx: Db = prisma,
): Promise<payments | null> => {
  if (!isUuid(paymentId)) {
    return null;
  }
  return tx.payments.findFirst({
    where: {
      id: paymentId,
      org_id: actor.orgId,
      ...(actor.kind === "tenant"
        ? { leases: { tenant_id: actor.tenantId } }
        : {}),
    },
  });
};

export const requireVisiblePayment = async (
  actor: Actor,
  paymentId: string,
  tx: Db = prisma,
): Promise<payments> => {
  const payment = await findVisiblePayment(actor, paymentId, tx);
  if (!payment) {
    throw notFound();
  }
  return payment;
};

// Assertion signatures need an explicit type annotation on an arrow function.
export const requireMember: (actor: Actor) => asserts actor is MemberActor = (
  actor,
) => {
  if (actor.kind !== "member") {
    throw forbidden();
  }
};

export const requireManager: (
  actor: Actor,
) => asserts actor is ManagerActor = (actor) => {
  if (actor.kind !== "member" || actor.role !== "manager") {
    throw forbidden();
  }
};
import "server-only";
import type { Prisma } from "@/generated/prisma/client";

// Money-moving building blocks. Every function takes the caller's transaction:
// they are only correct inside one that has already called lockLease().
//
// Lock order (the same everywhere, so two transactions never deadlock):
//   1. the lease row (lockLease)            — serializes all money on a lease
//   2. the payment row, if any (FOR UPDATE)
//   3. invoice/payment rows touched by the allocation trigger (FOR NO KEY UPDATE)

export type Tx = Prisma.TransactionClient;

export type LeaseTotals = {
  invoicedSen: bigint;
  allocatedSen: bigint;
  pendingSen: bigint;
};

export type AuditEntry = {
  orgId: string;
  actorId: string | null;
  action: string;
  entityId: string | null;
  details: Prisma.InputJsonObject;
};

type UnpaidInvoiceRow = { id: string; unpaid_sen: bigint };
type TotalsRow = { invoiced: bigint; allocated: bigint; pending: bigint };

/**
 * Takes the lease row lock. Every money-moving transaction on a lease calls
 * this FIRST, so cap checks, approvals, voids and webhook settlements on one
 * lease run one at a time and each sees the previous one's committed rows.
 * Returns false if the lease does not exist.
 */
export const lockLease = async (tx: Tx, leaseId: string): Promise<boolean> => {
  const rows = await tx.$queryRaw<{ id: string }[]>`
    SELECT id FROM public.leases WHERE id = ${leaseId}::uuid FOR UPDATE`;
  return rows.length > 0;
};

/** Sums for the cap: total invoiced, total allocated, total still pending_verification. */
export const leaseTotals = async (
  tx: Tx,
  leaseId: string,
): Promise<LeaseTotals> => {
  const rows = await tx.$queryRaw<TotalsRow[]>`
    SELECT
      (SELECT coalesce(sum(i.amount_sen), 0)::bigint
         FROM public.invoices i
        WHERE i.lease_id = ${leaseId}::uuid) AS invoiced,
      (SELECT coalesce(sum(a.amount_sen), 0)::bigint
         FROM public.payment_allocations a
         JOIN public.invoices i ON i.id = a.invoice_id
        WHERE i.lease_id = ${leaseId}::uuid) AS allocated,
      (SELECT coalesce(sum(p.amount_sen), 0)::bigint
         FROM public.payments p
        WHERE p.lease_id = ${leaseId}::uuid
          AND p.status = 'pending_verification') AS pending`;
  const row = rows[0];
  if (!row) {
    throw new Error("leaseTotals returned no row");
  }
  return {
    invoicedSen: BigInt(row.invoiced),
    allocatedSen: BigInt(row.allocated),
    pendingSen: BigInt(row.pending),
  };
};

/**
 * Allocates an approved payment to its lease's invoices that still have
 * something unpaid, in allocation order (due date, deposit before rent, period
 * index), filling each before the next — including invoices not due yet.
 * Whatever is left is stored as unapplied_sen. Caller holds the lease lock.
 */
export const allocatePayment = async (
  tx: Tx,
  paymentId: string,
): Promise<void> => {
  const payment = await tx.payments.findUnique({
    where: { id: paymentId },
    select: {
      id: true,
      org_id: true,
      lease_id: true,
      amount_sen: true,
      status: true,
      _count: { select: { payment_allocations: true } },
    },
  });
  if (!payment) {
    throw new Error(`Payment ${paymentId} not found`);
  }
  if (payment.status !== "approved") {
    throw new Error(`Payment ${paymentId} is ${payment.status}, not approved`);
  }
  if (payment._count.payment_allocations > 0) {
    throw new Error(`Payment ${paymentId} is already allocated`);
  }

  const invoices = await tx.$queryRaw<UnpaidInvoiceRow[]>`
    SELECT i.id,
           (i.amount_sen - coalesce(sum(a.amount_sen), 0))::bigint AS unpaid_sen
      FROM public.invoices i
      LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
     WHERE i.lease_id = ${payment.lease_id}::uuid
     GROUP BY i.id
    HAVING i.amount_sen - coalesce(sum(a.amount_sen), 0) > 0
     ORDER BY i.due_date, (i.kind = 'deposit') DESC, i.period_index, i.id`;

  let remaining = payment.amount_sen;
  const allocations: Prisma.payment_allocationsCreateManyInput[] = [];
  for (const invoice of invoices) {
    if (remaining <= 0n) {
      break;
    }
    const unpaid = BigInt(invoice.unpaid_sen);
    const amount = remaining < unpaid ? remaining : unpaid;
    allocations.push({
      org_id: payment.org_id,
      payment_id: payment.id,
      invoice_id: invoice.id,
      amount_sen: amount,
    });
    remaining -= amount;
  }

  if (allocations.length > 0) {
    await tx.payment_allocations.createMany({ data: allocations });
  }
  if (remaining > 0n) {
    await tx.payments.update({
      where: { id: payment.id },
      data: { unapplied_sen: remaining },
    });
  }
};

/** Appends one audit_log row (append-only table) inside the caller's transaction. */
export const writeAudit = async (tx: Tx, entry: AuditEntry): Promise<void> => {
  await tx.audit_log.create({
    data: {
      org_id: entry.orgId,
      actor_id: entry.actorId,
      action: entry.action,
      entity_id: entry.entityId,
      details: entry.details,
    },
  });
};

